 }

 .dashboard-workspace {
 min-width: 0;
 min-height: 100vh;
 min-height: 100svh;
 display: flex;
 flex-direction: column;
 }

 .dashboard-topbar {
 min-height: 94px;
 position: sticky;
 top: 0;
 z-index: 40;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 24px;
 border-bottom: 1px solid #dbe9df;
 padding: 14px 30px 14px 36px;
 background: rgba(255, 255, 255, 0.98);
 }

 .dashboard-topbar-heading {
 flex: 1 1 auto;
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 14px;
 color: #176f3d;
 font-size: 20px;
 font-weight: 700;
 }

 .dashboard-topbar-title {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 }

 .dashboard-menu-button,
 .dashboard-icon-button {
 width: 44px;
 height: 44px;
 display: grid;
 place-items: center;
 border: 0;
 border-radius: 6px;
 padding: 0;
 color: #687285;
 background: transparent;
 cursor: pointer;
 transition: color 160ms ease, background 160ms ease;
 }

 .dashboard-menu-button {
 display: none;
 }

 .dashboard-icon-button:hover,
 .dashboard-menu-button:hover {
 color: #177645;
 background: #edf7f0;
 }

 .dashboard-topbar-actions {
