 align-items: center;
 gap: 10px;
 }

 .dashboard-menu-wrap {
 position: relative;
 }

 .dashboard-notification-count {
 min-width: 19px;
 height: 19px;
 position: absolute;
 top: 1px;
 right: 0;
 display: grid;
 place-items: center;
 border: 2px solid #ffffff;
 border-radius: 10px;
 padding: 0 4px;
 color: #ffffff;
 background: #dc2626;
 font-size: 10px;
 font-weight: 700;
 }

 .dashboard-profile-button {
 min-width: 0;
 min-height: 62px;
 display: flex;
 align-items: center;
 gap: 12px;
 border: 0;
 border-radius: 6px;
 padding: 4px 8px;
 color: #111827;
 background: transparent;
 cursor: pointer;
 transition: background 160ms ease;
 }

 .dashboard-profile-button:hover {
 background: #f3f7f4;
 }

 .dashboard-profile-name {
 max-width: 190px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 font-size: 20px;
 }

 .dashboard-dropdown {
 position: absolute;
 top: calc(100% + 12px);
 z-index: 80;
 overflow: hidden;
 border: 1px solid #dce5df;
 border-radius: 8px;
 background: #ffffff;
 box-shadow: 0 18px 44px rgba(28, 44, 35, 0.17);
 }

 .dashboard-dropdown[hidden] {
 display: none;
 }

 .dashboard-notification-menu {
 width: min(450px, calc(100vw - 28px));
 right: 0;
 max-height: min(640px, calc(100vh - 124px));
 overflow-y: auto;
 }

 .dashboard-dropdown-header {
 min-height: 56px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 16px;
 border-bottom: 1px solid #edf1ee;
 padding: 12px 16px;
 }

 .dashboard-dropdown-header strong {
 font-size: 16px;
 }

 .dashboard-text-button {
 border: 0;
 padding: 6px 0;
 color: #176f3d;
 background: transparent;
 font-size: 13px;
 font-weight: 600;
 cursor: pointer;
 }

 .dashboard-text-button:hover {
 text-decoration: underline;
 }

 .dashboard-notification-item {
 min-height: 94px;
 position: relative;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr) auto;
 align-items: start;
 gap: 12px;
 border-bottom: 1px solid #edf1ee;
 padding: 14px 16px;
 color: #111827;
 text-decoration: none;
 transition: background 150ms ease;
 }

 .dashboard-notification-item:hover,
 .dashboard-notification-item.is-unread {
 background: #f5fbf7;
 }

 .dashboard-notification-icon {
 width: 40px;
 height: 40px;
 display: grid;
 place-items: center;
 border-radius: 8px;
 color: #177645;
 background: #e8f6ed;
 }

 .dashboard-notification-icon.tone-blue {
 color: #2563eb;
 background: #eaf1ff;
 }

 .dashboard-notification-icon.tone-orange {
 color: #ea580c;
 background: #fff1e8;
 }

 .dashboard-notification-icon.tone-violet {
 color: #7c3aed;
 background: #f2ebff;
 }

 .dashboard-notification-icon.tone-red {
 color: #dc2626;
 background: #feecec;
 }

 .dashboard-notification-copy {
 min-width: 0;
 display: grid;
 gap: 3px;
 }

 .dashboard-notification-copy strong {
 font-size: 14px;
 }

 .dashboard-notification-copy span {
 color: #4b5563;
 font-size: 13px;
 line-height: 1.4;
 }

 .dashboard-notification-copy small {
 color: #6b7280;
 font-size: 12px;
 }

 .dashboard-unread-dot {
 width: 9px;
 height: 9px;
 align-self: center;
 border-radius: 50%;
 background: #2563eb;
 }

 .dashboard-dropdown-empty {
 min-height: 245px;
 display: grid;
 justify-items: center;
 align-content: center;
 gap: 7px;
 padding: 22px;
 text-align: center;
 }

 .dashboard-dropdown-empty img {
 width: 104px;
 height: 84px;
 margin-bottom: 4px;
 }

 .dashboard-dropdown-empty strong {
 font-size: 15px;
 }

 .dashboard-dropdown-empty span {
 max-width: 280px;
 color: #667085;
 font-size: 13px;
 line-height: 1.45;
 }

 .dashboard-dropdown-footer {
 min-height: 50px;
 display: grid;
 place-items: center;
 color: #177645;
 font-size: 14px;
 font-weight: 700;
 text-decoration: none;
 }

 .dashboard-dropdown-footer:hover {
 background: #f2f8f4;
 }

 .dashboard-profile-menu {
 width: 210px;
 right: 0;
 padding: 7px;
 }

 .dashboard-profile-menu a,
 .dashboard-profile-menu button {
 width: 100%;
 min-height: 44px;
 display: flex;
 align-items: center;
 gap: 11px;
 border: 0;
 border-radius: 6px;
 padding: 9px 11px;
 color: #27313d;
 background: transparent;
 font-size: 14px;
 text-align: left;
 text-decoration: none;
 cursor: pointer;
 }

 .dashboard-profile-menu a:hover,
 .dashboard-profile-menu button:hover {
 color: #176f3d;
 background: #edf7f0;
 }

 .dashboard-content {
 width: min(100%, 1700px);
 flex: 1 0 auto;
 margin: 0 auto;
 padding: 20px 38px 42px;
 }

 .dashboard-flash {
 min-height: 46px;
 display: flex;
 align-items: center;
 gap: 10px;
 margin-bottom: 14px;
 border: 1px solid #9ed1ae;
 border-radius: 7px;
 padding: 10px 14px;
 color: #14532d;
 background: #ecfdf3;
 font-size: 14px;
 font-weight: 600;
 }

 .dashboard-breadcrumbs {
 min-width: 0;
 margin: 0;
 color: #667085;
 font-size: 14px;
 font-weight: 500;
 }

 .dashboard-breadcrumbs ol {
 display: flex;
 flex-wrap: nowrap;
 align-items: center;
 gap: 7px;
 margin: 0;
 padding: 0;
 list-style: none;
 }

 .dashboard-breadcrumbs li {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 7px;
 }

 .dashboard-breadcrumbs li:not(:last-child)::after {
 content: '/';
 color: #a0a8b3;
 }

 .dashboard-breadcrumbs a {
 color: #667085;
 text-decoration: none;
 white-space: nowrap;
 }

 .dashboard-breadcrumbs a:hover {
 color: #176f3d;
 text-decoration: underline;
 }

 .dashboard-breadcrumbs span[aria-current='page'] {
 display: block;
 overflow: hidden;
 color: #177645;
 font-weight: 600;
 text-overflow: ellipsis;
 white-space: nowrap;
 }

 .dashboard-page {
 display: grid;
 gap: 20px;
 }

 .dashboard-page-heading {
 display: grid;
 gap: 3px;
 padding: 0 4px;
 }

 .dashboard-page-heading h1 {
 margin: 0;
 color: #101828;
 font-size: 27px;
 line-height: 1.2;
 font-weight: 700;
 letter-spacing: 0;
 }

 .dashboard-page-heading p {
 margin: 0;
 color: #596780;
 font-size: 16px;
 line-height: 1.45;
 }

 .dashboard-page-heading-row {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 20px;
 }

 /* Keeps shared summary cards evenly spaced while allowing role-specific column counts. */
 .dashboard-summary-grid {
 display: grid;
 gap: 18px;
 align-items: stretch;
 }

 /* Uses three equal columns for the Adviser dashboard summary. */
 .dashboard-summary-grid-three {
 grid-template-columns: repeat(3, minmax(0, 1fr));
 }

 /* Uses four equal columns for Reviewer dashboard summaries. */
 .dashboard-summary-grid-four {
 grid-template-columns: repeat(4, minmax(0, 1fr));
 }

 /* Uses five equal columns for the RES Lead administrative summary. */
 .dashboard-summary-grid-five {
 grid-template-columns: repeat(5, minmax(0, 1fr));
 }

 /* Keeps the icon on the left and centers the number-label group in the remaining card width. */
 .dashboard-summary-card {
 min-width: 0;
 min-height: 132px;
 display: grid;
 grid-template-columns: 58px minmax(0, 1fr);
 align-items: center;
 gap: 16px;
 border: 1px solid #dce5e0;
 border-radius: 8px;
 padding: 18px;
 color: #111827;
 background: #ffffff;
 box-shadow: 0 5px 14px rgba(23, 56, 38, 0.06);
 text-align: center;
 text-decoration: none;
 transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
 }

 /* Retains the existing restrained hover lift without changing the card's fixed content geometry. */
 .dashboard-summary-card:hover {
 border-color: #8fbea0;
 box-shadow: 0 10px 22px rgba(23, 56, 38, 0.11);
 transform: translateY(-2px);
 }

 /* Vertically centers the existing colored icon within the card's fixed left column. */
 .dashboard-summary-icon {
 width: 58px;
 height: 58px;
 display: grid;
 place-items: center;
 border-radius: 50%;
 color: #177645;
 background: #eaf6ee;
 }

 /* Stacks the numerical count above its label in the complete right-side content area. */
 .dashboard-summary-copy {
 width: 100%;
 min-width: 0;
 display: grid;
 justify-items: center;
 gap: 5px;
 }

 /* Keeps the database-derived count visually prominent without affecting card height. */
 .dashboard-summary-copy strong {
 color: #177645;
 font-size: 36px;
 line-height: 1;
 font-weight: 700;
 }

 /* Centers one-line and wrapped labels beneath the corresponding numerical count. */
 .dashboard-summary-copy span {
 max-width: 18ch;
 color: #176f3d;
 font-size: 14px;
 line-height: 1.25;
 font-weight: 600;
 text-align: center;
 }

 .dashboard-summary-card.tone-orange .dashboard-summary-icon,
 .dashboard-status-badge.tone-orange {
 color: #f97316;
 background: #fff2e8;
 }

 .dashboard-summary-card.tone-orange .dashboard-summary-copy strong,
 .dashboard-summary-card.tone-orange .dashboard-summary-copy span {
 color: #f97316;
 }

 .dashboard-summary-card.tone-blue .dashboard-summary-icon,
 .dashboard-status-badge.tone-blue {
 color: #2563eb;
 background: #eaf1ff;
 }

 .dashboard-summary-card.tone-blue .dashboard-summary-copy strong,
 .dashboard-summary-card.tone-blue .dashboard-summary-copy span {
 color: #2563eb;
 }

 .dashboard-summary-card.tone-red .dashboard-summary-icon,
 .dashboard-status-badge.tone-red {
 color: #dc2626;
 background: #feecec;
 }

 .dashboard-summary-card.tone-red .dashboard-summary-copy strong,
 .dashboard-summary-card.tone-red .dashboard-summary-copy span {
 color: #dc2626;
 }

 .dashboard-summary-card.tone-violet .dashboard-summary-icon,
 .dashboard-status-badge.tone-violet {
 color: #6d28d9;
 background: #f1eaff;
 }

 .dashboard-summary-card.tone-violet .dashboard-summary-copy strong,
 .dashboard-summary-card.tone-violet .dashboard-summary-copy span {
 color: #6d28d9;
 }

 .dashboard-summary-card.tone-cyan .dashboard-summary-icon,
 .dashboard-status-badge.tone-cyan {
 color: #0e7490;
 background: #e7f8fb;
 }

 .dashboard-summary-card.tone-cyan .dashboard-summary-copy strong,
 .dashboard-summary-card.tone-cyan .dashboard-summary-copy span {
 color: #0e7490;
 }

 .dashboard-status-badge.tone-green,
 .dashboard-status-badge.tone-success {
 color: #15713f;
 background: #e7f6ec;
 }

 .dashboard-status-badge.tone-amber {
 color: #b45309;
 background: #fff5d9;
 }

 .dashboard-status-badge.tone-purple {
 color: #7e22ce;
 background: #f6eaff;
 }

 .dashboard-status-badge.tone-neutral {
 color: #4b5563;
 background: #f0f2f4;
 }

 .dashboard-panel,
 .dashboard-focus-card,
 .dashboard-record-summary,
 .dashboard-notification-list,
 .dashboard-placeholder {
 border: 1px solid #dce5e0;
 border-radius: 8px;
 background: #ffffff;
 box-shadow: 0 5px 14px rgba(23, 56, 38, 0.055);
 }

 .dashboard-panel {
 min-width: 0;
 overflow: hidden;
 }

 .dashboard-panel-header {
 min-height: 58px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 20px;
 padding: 13px 24px;
 }

 .dashboard-panel-header h2,
 .dashboard-focus-card h2 {
 margin: 0;
 color: #101828;
 font-size: 18px;
 line-height: 1.3;
 font-weight: 700;
 letter-spacing: 0;
 }

 .dashboard-panel-header-meta {
 display: inline-flex;
 align-items: center;
 justify-content: flex-end;
 gap: 8px;
 color: #177645;
 font-size: 13px;
 font-weight: 700;
 text-align: right;
 }

 .dashboard-view-all {
 min-width: 88px;
 min-height: 36px;
 display: inline-grid;
 place-items: center;
 border: 1px solid #248451;
 border-radius: 5px;
 padding: 6px 14px;
 color: #177645;
 background: #ffffff;
 font-size: 13px;
 font-weight: 700;
 text-decoration: none;
 transition: color 150ms ease, background 150ms ease;
 }

 .dashboard-view-all:hover {
 color: #ffffff;
 background: #177645;
 }

 .dashboard-panel-body {
 min-width: 0;
 }

 .dashboard-table-wrap {
