 overflow-x: auto;
 border-top: 1px solid #e6ece8;
 }

 .dashboard-table {
 width: 100%;
 min-width: 920px;
 border-collapse: collapse;
 color: #1f2937;
 font-size: 13px;
 }

 .dashboard-table th,
 .dashboard-table td {
 height: 48px;
 border-bottom: 1px solid #e6ece8;
 padding: 9px 22px;
 text-align: left;
 vertical-align: middle;
 }

 .dashboard-table .dashboard-table-status,
 .dashboard-table .dashboard-table-action {
 text-align: center;
 }

 .dashboard-table td.dashboard-table-status .dashboard-status-badge {
 min-width: 126px;
 margin-inline: auto;
 }

 .dashboard-table td.dashboard-table-action .dashboard-action-link {
 display: inline-block;
 min-width: 46px;
 text-align: center;
 }

 .dashboard-table th {
 color: #303944;
 background: #fbfcfb;
 font-size: 12px;
 font-weight: 700;
 white-space: nowrap;
 }

 .dashboard-table tbody tr:last-child td {
 border-bottom: 0;
 }

 .dashboard-table tbody tr:hover {
 background: #f7fbf8;
 }

 .dashboard-table td > a:not(.dashboard-action-link) {
 color: #273e6f;
 font-weight: 600;
 text-decoration: none;
 }

 .dashboard-table td > a:not(.dashboard-action-link):hover {
 color: #177645;
 text-decoration: underline;
 }

 .dashboard-action-link {
 color: #15803d;
 font-weight: 700;
 text-decoration: none;
 }

 .dashboard-action-link:hover {
 text-decoration: underline;
 }

 .dashboard-research-title {
 width: 100%;
 max-width: 320px;
 display: block;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 }

 .dashboard-title-tooltip {
 width: max-content;
 max-width: min(430px, calc(100vw - 24px));
 position: fixed;
 z-index: 120;
 border: 1px solid #cfdad3;
 border-radius: 6px;
 padding: 9px 11px;
 color: #ffffff;
 background: #173d2d;
 box-shadow: 0 10px 26px rgba(17, 43, 31, 0.2);
 font-size: 13px;
 line-height: 1.4;
 pointer-events: none;
 }

 .dashboard-title-tooltip[hidden] {
 display: none;
 }

 .dashboard-status-badge {
 width: fit-content;
 max-width: 100%;
 min-height: 28px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 8px;
 border-radius: 5px;
 padding: 5px 12px;
 font-size: 12px;
 line-height: 1.2;
 font-weight: 600;
 text-align: center;
 }

 .dashboard-status-dot {
 width: 8px;
 height: 8px;
 flex: 0 0 8px;
 border-radius: 50%;
 background: currentColor;
 }

 .dashboard-empty-state {
 min-height: 245px;
 display: grid;
 justify-items: center;
 align-content: center;
 gap: 8px;
 padding: 24px;
 text-align: center;
 }

 .dashboard-empty-state.is-compact {
