 line-height: 1.55;
 }

 .dashboard-primary-action,
 .dashboard-outline-action,
 .dashboard-danger-action {
 min-height: 42px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 9px;
 border: 1px solid #1b804b;
 border-radius: 6px;
 padding: 9px 22px;
 font-size: 14px;
 font-weight: 700;
 text-decoration: none;
 cursor: pointer;
 transition: color 150ms ease, background 150ms ease, box-shadow 150ms ease;
 }

 .dashboard-primary-action {
 margin-top: 0;
 color: #ffffff;
 background: #18864f;
 }

 .dashboard-primary-action:hover {
 background: #147442;
 box-shadow: 0 8px 18px rgba(24, 134, 79, 0.2);
 }

 .dashboard-outline-action {
 color: #177645;
 background: #ffffff;
 }

 .dashboard-outline-action:hover,
 .dashboard-outline-action:focus-visible {
 color: #ffffff;
 background: #177645;
 }

 .dashboard-outline-action:disabled {
 border-color: #cbd2d8;
 color: #9ca3af;
 background: #ffffff;
 cursor: not-allowed;
 }

 .dashboard-danger-action {
 color: #ffffff;
 background: #b42318;
 border-color: #b42318;
 }

 .dashboard-danger-action:hover,
 .dashboard-danger-action:focus-visible {
 background: #8f1c13;
 border-color: #8f1c13;
 box-shadow: 0 8px 18px rgba(180, 35, 24, 0.18);
 }

 .dashboard-lower-grid {
 display: grid;
 grid-template-columns: minmax(320px, 0.8fr) minmax(520px, 1.45fr);
 gap: 20px;
 }

 .dashboard-lower-grid > .dashboard-panel {
 min-height: 320px;
 }

 .dashboard-deadline-active {
 min-height: 240px;
 display: flex;
 align-items: center;
 justify-content: center;
 gap: 28px;
 padding: 28px;
 }

 .dashboard-deadline-icon {
 width: 112px;
 height: 112px;
 flex: 0 0 112px;
 display: grid;
 place-items: center;
 border-radius: 50%;
 color: #dc2626;
 background: #feecec;
 }

 .dashboard-deadline-active > div {
 display: grid;
 gap: 9px;
 }

 .dashboard-deadline-active span {
 color: #303944;
 font-size: 15px;
 line-height: 1.4;
 }

 .dashboard-deadline-active strong {
 color: #dc2626;
 font-size: 34px;
 line-height: 1;
 }

 .dashboard-deadline-active small {
 color: #506080;
 font-size: 14px;
 font-weight: 600;
 }

 .dashboard-deadline-list {
 min-height: 250px;
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: center;
 gap: 24px;
 padding: 24px;
 }

 .dashboard-deadline-list > div {
 min-width: 0;
 display: grid;
 gap: 12px;
 }

 .dashboard-deadline-list > div > strong {
 color: #dc2626;
 font-size: 17px;
 }

 .dashboard-deadline-list ul {
 display: grid;
 gap: 8px;
 margin: 0;
 padding: 0;
 list-style: none;
 }

 .dashboard-deadline-list li {
 display: flex;
 justify-content: space-between;
 gap: 16px;
 color: #354466;
 font-size: 12px;
 }

 .dashboard-deadline-list time {
 white-space: nowrap;
 font-weight: 600;
 }

 .dashboard-deadline-list a {
 display: inline-flex;
 align-items: center;
 gap: 7px;
 color: #15803d;
 font-size: 13px;
 font-weight: 700;
 text-decoration: none;
 }

 .dashboard-timeline {
 min-height: 250px;
 padding: 8px 24px 18px;
 }

 .dashboard-timeline ol {
 margin: 0;
 padding: 0;
 list-style: none;
 }

 .dashboard-timeline li {
 min-height: 38px;
 position: relative;
 display: grid;
 grid-template-columns: 28px minmax(180px, 1fr) auto;
 align-items: center;
 gap: 8px;
 border-bottom: 1px dashed #d9e0dc;
 color: #263142;
 font-size: 13px;
 }

 .dashboard-timeline li:last-child {
 border-bottom: 0;
 }

 .dashboard-timeline li:not(:last-child)::before {
 content: '';
 width: 2px;
 position: absolute;
 top: 25px;
 bottom: -14px;
 left: 10px;
 background: #c7d0d8;
 }

 .dashboard-timeline-marker {
 width: 20px;
 height: 20px;
 position: relative;
 z-index: 1;
 display: grid;
 place-items: center;
 border: 2px solid #aeb9c8;
 border-radius: 50%;
 color: #ffffff;
 background: #ffffff;
 }

 .dashboard-timeline li.is-complete .dashboard-timeline-marker {
 border-color: #168347;
