 padding: 20px 16px;
 }

 .dashboard-deadline-active,
 .dashboard-deadline-list {
 grid-template-columns: 1fr;
 flex-direction: column;
 text-align: center;
 }

 .dashboard-deadline-list {
 justify-items: center;
 }

 .dashboard-deadline-list li {
 display: grid;
 gap: 3px;
 }

 .dashboard-deadline-list a {
