 }
 }

 @layer components {
 /* Certificate Processing follows a queue-first hierarchy; record workflows stay inside focused dialogs. */
 .certificate-page-heading {
 align-items: flex-end;
 }

 .certificate-page-actions {
 display: flex;
 flex-wrap: wrap;
 justify-content: flex-end;
 gap: 10px;
 }

 .certificate-page-actions > * {
 min-height: 42px;
 justify-content: center;
 }

 .certificate-metric-strip {
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 overflow: hidden;
 }

 .certificate-metric-strip article {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 14px;
 padding: 18px 20px;
 border-left: 1px solid #e3e9e5;
 }

 .certificate-metric-strip article:first-child {
 border-left: 0;
 }

 .certificate-metric-strip article > div {
 min-width: 0;
 display: grid;
 gap: 2px;
 }

 .certificate-metric-strip strong {
 color: #075c35;
 font-size: 25px;
 line-height: 1;
 }

 .certificate-metric-strip article:nth-child(3) strong {
