 }

 .certificate-metric-strip article:nth-child(4) strong {
 color: #1267d5;
 }

 .certificate-metric-strip article > div span {
 color: #526071;
 font-size: 12px;
 font-weight: 600;
 }

 .certificate-metric-icon {
