 height: 46px;
 flex: 0 0 46px;
 display: grid;
 place-items: center;
 border-radius: 9px;
 }

 .certificate-metric-icon.is-green {
 color: #087241;
 background: #e8f5ed;
 }

 .certificate-metric-icon.is-orange {
 color: #e06000;
 background: #fff0e3;
 }

 .certificate-metric-icon.is-blue {
 color: #1267d5;
 background: #e8f1ff;
 }

 .certificate-queue-filters {
 grid-template-columns: repeat(4, minmax(150px, 1fr));
 gap: 14px;
 padding: 16px 18px;
 }

 .certificate-filter-search {
 grid-column: span 2;
 }

 .certificate-filter-actions {
 grid-column: span 2;
 display: flex;
 align-items: end;
 justify-content: flex-end;
 gap: 10px;
 }

 .certificate-queue-filters .application-field {
