 font-size: 12px;
 }

 .certificate-queue-table th,
 .certificate-queue-table td {
 height: 62px;
 padding: 10px 12px;
 }

 .certificate-queue-table th:first-child,
 .certificate-queue-table td:first-child {
 width: 42px;
 padding-right: 2px;
 text-align: center;
 }

 .certificate-queue-table th:nth-child(2) {
