 }

 .certificate-queue-table .certificate-queue-centered {
 text-align: center;
 }

 .certificate-queue-table td.certificate-queue-centered .dashboard-status-badge,
 .certificate-queue-table td.certificate-queue-centered .certificate-row-action {
 margin-inline: auto;
 }

 .certificate-updated-cell.certificate-queue-centered {
