 }

 .certificate-background-modal > .application-modal-heading {
 padding: 22px 54px 18px 22px;
 }

 .certificate-background-modal > .certificate-background-current {
 margin: 0 22px 18px;
 }

 .certificate-background-current-actions {
 display: flex;
 flex-wrap: wrap;
 align-items: center;
 justify-content: flex-end;
 gap: 8px;
 }

 .certificate-background-upload {
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto;
 align-items: end;
 gap: 10px 14px;
 }

 .certificate-background-upload > .certificate-modal-section-heading {
 grid-column: 1 / -1;
 margin-bottom: 0;
 }

 .certificate-background-upload form:first-of-type {
 display: flex;
 align-items: end;
 gap: 10px;
 }

 .certificate-background-upload form:first-of-type label {
 min-width: 0;
 flex: 1 1 auto;
 display: grid;
 gap: 5px;
 font-size: 11px;
 font-weight: 750;
 }

 .certificate-background-upload input[type='file'] {
 width: 100%;
 min-height: 40px;
 border: 1px solid #cbd8d1;
 border-radius: 6px;
 padding: 6px;
 background: #ffffff;
 }

 .certificate-background-row-actions {
 display: flex;
 align-items: center;
 gap: 9px;
 }

 .certificate-background-row-actions form,
 .certificate-background-row-actions button {
 display: inline;
 margin: 0;
 border: 0;
 padding: 0;
 background: transparent;
 cursor: pointer;
 }

 .certificate-background-modal .identity-pagination {
 margin: 12px 0 0;
 }

 .application-modal.certificate-bulk-modal {
 width: min(100%, 520px);
 }

 .certificate-bulk-options {
 display: grid;
 gap: 8px;
 margin: 0 0 14px;
 border: 0;
 padding: 0;
 }

 .certificate-bulk-options legend {
 margin-bottom: 8px;
 color: #1f2e25;
 font-size: 12px;
 font-weight: 750;
 }

 .certificate-bulk-options label {
 display: grid;
 grid-template-columns: auto minmax(0, 1fr);
 align-items: center;
 gap: 11px;
 min-height: 54px;
 border: 1px solid #dce6df;
 border-radius: 8px;
 padding: 9px 12px;
 background: #fff;
 cursor: pointer;
 }

 .certificate-bulk-options label:has(input:checked) {
 border-color: #15834a;
 box-shadow: 0 0 0 1px #15834a;
 background: #f2faf5;
 }

 .certificate-bulk-options input {
 width: 17px;
 height: 17px;
 accent-color: #15834a;
 }

 .certificate-bulk-options span {
 display: grid;
 gap: 2px;
 }

 .certificate-bulk-options strong {
 color: #17231c;
 font-size: 13px;
 }

 .certificate-bulk-options small {
 color: #64748b;
 font-size: 11px;
 }

 .certificate-bulk-confirmation-copy {
 display: flex;
 align-items: flex-start;
 gap: 10px;
 border: 1px solid #dce6df;
 border-radius: 7px;
 padding: 12px;
 color: #405249;
 background: #f6faf7;
 }

 .certificate-bulk-confirmation-copy p {
 margin: 0;
 font-size: 12px;
 line-height: 1.5;
 }
 }

 @media (max-width: 1100px) {
 .certificate-metric-strip {
 grid-template-columns: repeat(2, minmax(0, 1fr));
 }

 .certificate-metric-strip article:nth-child(3) {
 border-top: 1px solid #e3e9e5;
 border-left: 0;
 }

 .certificate-metric-strip article:nth-child(4) {
 border-top: 1px solid #e3e9e5;
 }

 .certificate-modal-status-grid {
 grid-template-columns: repeat(3, minmax(0, 1fr));
 }

 .certificate-modal-status-grid > div:nth-child(4) {
 border-top: 1px solid #e5eae7;
 border-left: 0;
 }

 .certificate-modal-status-grid > div:nth-child(5) {
 border-top: 1px solid #e5eae7;
 }
 }

 @media (max-width: 820px) {
 .certificate-page-heading {
 align-items: stretch;
 flex-direction: column;
 }

 .certificate-page-actions {
 justify-content: stretch;
 }

 .certificate-page-actions > * {
 flex: 1 1 240px;
 }

 .certificate-queue-filters {
 grid-template-columns: repeat(2, minmax(0, 1fr));
 }

 .certificate-modal-heading,
 .certificate-decision-controls,
 .certificate-background-callout {
 align-items: stretch;
 flex-direction: column;
 }

 .certificate-modal-heading > .dashboard-status-badge {
 align-self: flex-start;
 }

 .certificate-reviewer-decisions {
 grid-template-columns: minmax(0, 1fr);
 }

 .certificate-decision-controls label {
 width: 100%;
 min-width: 0;
 }

 .certificate-background-upload {
 grid-template-columns: minmax(0, 1fr);
 }

 .certificate-background-upload > .certificate-modal-section-heading {
 grid-column: auto;
 }

 .certificate-background-upload form:first-of-type {
 align-items: stretch;
 flex-direction: column;
 }
 }

 @media (max-width: 560px) {
 .application-modal-backdrop:has(.certificate-application-modal),
 .application-modal-backdrop:has(.certificate-background-modal) {
 padding: 8px;
 }

 .certificate-metric-strip,
 .certificate-queue-filters,
 .certificate-modal-status-grid,
 .certificate-revision-document-picker {
