 }

 .certificate-metric-strip article,
 .certificate-metric-strip article:nth-child(3),
 .certificate-metric-strip article:nth-child(4) {
 border-top: 1px solid #e3e9e5;
 border-left: 0;
 }

 .certificate-metric-strip article:first-child {
 border-top: 0;
 }

 .certificate-page-actions {
 flex-direction: column;
 }

 .certificate-page-actions > * {
 width: 100%;
 flex: 0 0 auto;
 }

 .certificate-modal-status-grid > div,
 .certificate-modal-status-grid > div:nth-child(4),
 .certificate-modal-status-grid > div:nth-child(5) {
 border-top: 1px solid #e5eae7;
 border-left: 0;
 }

 .certificate-modal-status-grid > div:first-child {
 border-top: 0;
 }

 .certificate-modal-actions,
 .certificate-modal-actions > form,
 .certificate-modal-actions > details,
 .certificate-modal-actions .dashboard-primary-action,
 .certificate-modal-actions .dashboard-outline-action,
 .certificate-background-upload form,
 .certificate-background-upload button {
 width: 100%;
 }

 .certificate-background-current,
 .certificate-background-current-actions {
 align-items: stretch;
 flex-direction: column;
 }

 .certificate-modal-heading,
 .certificate-modal-section,
 .certificate-modal-footer {
 padding-right: 16px;
 padding-left: 16px;
 }

 .certificate-background-modal > .certificate-background-current {
 margin-right: 16px;
 margin-left: 16px;
 }
 }

 @layer components {
 /* User management uses one restrained control language across listing, creation, and profile screens. */
 .identity-management-page {
 width: 100%;
 max-width: 1480px;
 margin-inline: auto;
 gap: 18px;
 }

 .identity-page-heading {
 min-width: 0;
 }

 .identity-heading-actions,
 .identity-filter-actions,
 .identity-form-actions,
 .identity-dialog-actions,
 .identity-success-actions {
 display: flex;
 align-items: center;
 gap: 10px;
 }

 .identity-button {
 min-height: 42px;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 gap: 8px;
 border: 1px solid transparent;
 border-radius: 6px;
 padding: 9px 16px;
 font-size: 13px;
 line-height: 1.2;
 font-weight: 700;
 text-align: center;
 text-decoration: none;
 cursor: pointer;
 transition: color 150ms ease, background 150ms ease, border-color 150ms ease;
 }

 .identity-button-primary {
 color: #ffffff;
 background: #167645;
 border-color: #167645;
 }

 .identity-button-primary:hover {
 background: #105f37;
 border-color: #105f37;
 }

 .identity-button-secondary {
 color: #176f3d;
 background: #ffffff;
 border-color: #8dbda0;
 }

 .identity-button-secondary:hover {
 color: #105f37;
 background: #edf7f0;
 border-color: #5c9e74;
 }

 .identity-button-danger {
 color: #b42318;
 background: #ffffff;
 border-color: #e9a8a2;
 }

 .identity-button-danger:hover {
 color: #ffffff;
 background: #b42318;
 border-color: #b42318;
 }

 .identity-role-tabs {
 min-width: 0;
 display: grid;
 grid-template-columns: repeat(4, minmax(0, 1fr));
 overflow: hidden;
 border: 1px solid #dbe5df;
 border-radius: 7px;
 background: #ffffff;
 }

 .identity-role-tabs.is-two {
 grid-template-columns: repeat(2, minmax(0, 1fr));
 }

 .identity-role-tabs.is-one {
 grid-template-columns: minmax(0, 1fr);
 }

 .identity-role-tabs a {
 min-width: 0;
 min-height: 54px;
 display: flex;
 align-items: center;
 justify-content: center;
 gap: 9px;
 border-right: 1px solid #e3e9e5;
 padding: 9px 14px;
 color: #2f3a4c;
 font-size: 14px;
 font-weight: 700;
 text-decoration: none;
 }

 .identity-role-tabs a:last-child {
 border-right: 0;
 }

 .identity-role-tabs a:hover {
 color: #176f3d;
 background: #f5faf7;
 }

 .identity-role-tabs a.is-active {
 color: #ffffff;
 background: #177845;
 }

 .identity-role-tabs small {
 min-width: 24px;
 min-height: 22px;
 display: inline-grid;
 place-items: center;
 border-radius: 11px;
 padding-inline: 6px;
 color: #176f3d;
 background: #e8f4ec;
 font-size: 11px;
 }

 .identity-role-tabs a.is-active small {
 color: #155d36;
 background: #ffffff;
 }

 .identity-filter-bar {
 display: grid;
 grid-template-columns: minmax(240px, 1.35fr) repeat(3, minmax(150px, 0.8fr)) auto;
 align-items: end;
 gap: 13px;
 border: 1px solid #dbe5df;
 border-radius: 7px;
 padding: 14px 16px;
 background: #ffffff;
 }

 .identity-filter-bar.is-adviser-filter {
 grid-template-columns: minmax(240px, 1.3fr) repeat(3, minmax(150px, 0.8fr)) auto;
 }

 .identity-filter {
 min-width: 0;
 display: grid;
 gap: 6px;
 }

 .identity-filter label,
 .identity-field label {
 color: #27313d;
 font-size: 12px;
 font-weight: 700;
 }

 .identity-filter input,
 .identity-filter select,
 .identity-field input {
 width: 100%;
 min-width: 0;
 min-height: 42px;
 border: 1px solid #cfd9d3;
 border-radius: 5px;
 padding: 9px 11px;
 color: #1f2937;
 background: #ffffff;
 font-size: 13px;
 outline: none;
 }

 .identity-filter input:focus,
 .identity-filter select:focus,
 .identity-field input:focus {
 border-color: #278e58;
 box-shadow: 0 0 0 3px rgba(39, 142, 88, 0.14);
 }

 .identity-input-icon {
 position: relative;
 }

 .identity-input-icon .dashboard-icon {
 position: absolute;
 top: 50%;
 left: 11px;
 color: #667085;
 transform: translateY(-50%);
 pointer-events: none;
 }

 .identity-input-icon input {
 padding-left: 39px;
 }

 .identity-filter-actions {
 min-height: 42px;
 }

 .identity-filter-actions > a {
 color: #596780;
 font-size: 12px;
 font-weight: 700;
 text-decoration: none;
 }

 .identity-filter-actions > a:hover {
 color: #176f3d;
 text-decoration: underline;
 }

 .identity-table-panel {
 min-width: 0;
 overflow: hidden;
 border: 1px solid #dbe5df;
 border-radius: 7px;
 background: #ffffff;
 }

 .identity-table-summary {
 min-height: 52px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 18px;
 padding: 10px 16px;
 color: #344054;
 font-size: 12px;
 }

 .identity-table-summary > a {
 min-height: 34px;
 display: inline-flex;
 align-items: center;
 gap: 7px;
 border: 1px solid #a4ceb2;
 border-radius: 5px;
 padding: 6px 10px;
 color: #177645;
 font-weight: 700;
 text-decoration: none;
 }

 .identity-table-summary > a:hover {
 background: #edf7f0;
 }

 .identity-table-scroll {
 width: 100%;
 overflow-x: auto;
 border-top: 1px solid #e5ebe7;
 border-bottom: 1px solid #e5ebe7;
 }

 .identity-user-table {
 width: 100%;
 min-width: 1180px;
 border-collapse: collapse;
 color: #344054;
 font-size: 12px;
 }

 .identity-user-table th,
 .identity-user-table td {
 min-width: 112px;
 height: 58px;
 border-bottom: 1px solid #e8ecea;
 padding: 10px 14px;
 text-align: left;
 vertical-align: middle;
 }

 .identity-user-table th:first-child,
 .identity-user-table td:first-child {
 min-width: 190px;
 }

 .identity-user-table th:nth-child(3),
 .identity-user-table td:nth-child(3) {
