 }

 .identity-user-table td > a:not(.identity-view-link) {
 color: #314b77;
 text-decoration: none;
 }

 .identity-user-table td > a:not(.identity-view-link):hover {
 text-decoration: underline;
 }

 .identity-table-person {
 min-width: 0;
 display: flex;
 align-items: center;
 gap: 9px;
 }

 .identity-table-person strong {
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 }

 .identity-mini-avatar {
 width: 34px;
 height: 34px;
 flex: 0 0 34px;
 display: grid;
 place-items: center;
 border-radius: 50%;
 color: #176f3d;
 background: #eaf5ed;
 font-size: 11px;
 font-weight: 800;
 }

 .identity-table-unit {
 min-width: 0;
 display: grid;
 gap: 2px;
 }

 .identity-table-unit strong,
 .identity-table-unit small {
 max-width: 190px;
 overflow: hidden;
 text-overflow: ellipsis;
 white-space: nowrap;
 }

 .identity-table-unit small {
 color: #667085;
 }

 .identity-view-link {
 color: #15803d;
 font-weight: 800;
 text-decoration: none;
 }

 .identity-view-link:hover {
 text-decoration: underline;
 }

 .identity-empty-row td {
 height: 350px;
 }

 .identity-empty-state {
 display: grid;
 justify-items: center;
 gap: 8px;
 padding: 36px;
 text-align: center;
 }

 .identity-empty-state > span,
 .identity-import-icon {
 width: 88px;
 height: 88px;
 display: grid;
 place-items: center;
 border-radius: 50%;
 color: #2f8959;
 background: #edf7f0;
 }

 .identity-empty-state strong {
 color: #172033;
 font-size: 20px;
 }

 .identity-empty-state p {
 margin: 0;
 color: #667085;
 font-size: 13px;
 }

 .identity-empty-state a {
 color: #177645;
 font-size: 13px;
 font-weight: 700;
 }

 .identity-pagination {
 min-height: 56px;
 display: flex;
 align-items: center;
 justify-content: flex-end;
 gap: 12px;
 padding: 10px 16px;
 color: #475467;
 font-size: 12px;
 }

 .identity-pagination a,
 .identity-pagination > span {
 min-width: 78px;
 min-height: 34px;
 display: inline-grid;
 place-items: center;
 border: 1px solid #d2dbd6;
 border-radius: 5px;
 padding: 6px 10px;
 color: #176f3d;
 font-weight: 700;
 text-decoration: none;
 }

 .identity-pagination > span {
 color: #98a2b3;
 background: #f8faf9;
 }

 .identity-dialog,
 .identity-form-card,
 .identity-success-panel,
 .identity-profile-hero,
 .identity-detail-panel,
 .identity-import-guide,
 .identity-import-form {
