 padding: 28px;
 }

 .identity-role-dialog {
 display: grid;
 gap: 22px;
 }

 .identity-dialog-heading {
 display: flex;
 align-items: center;
 gap: 13px;
 }

 .identity-dialog-heading h2,
 .identity-dialog-heading p,
 .identity-form-heading h2,
 .identity-form-heading p {
 margin: 0;
 }

 .identity-dialog-heading h2,
 .identity-form-heading h2,
 .identity-panel-heading h2,
 .identity-import-guide h2,
 .identity-import-form h2 {
