 color: #667085;
 font-size: 13px;
 }

 .identity-section-icon,
 .identity-role-option-icon {
 width: 46px;
 height: 46px;
 flex: 0 0 46px;
 display: grid;
 place-items: center;
 border-radius: 50%;
 color: #177645;
 background: #e9f6ed;
 }

 .identity-role-options {
