 display: none;
 place-items: center;
 border: 2px solid #ffffff;
 border-radius: 50%;
 color: #ffffff;
 background: #dc2626;
 font-size: 12px;
 line-height: 1;
 font-weight: 900;
 pointer-events: none;
 }

 /* Applies a persistent, non-color-only error state while unresolved validation details are available. */
 .identity-import-errors-button.has-errors {
