 background: #ffffff;
 border-color: #dc2626;
 }

 /* Reveals the fixed-position exclamation badge without shifting the action row. */
 .identity-import-errors-button.has-errors .identity-import-error-badge {
 display: grid;
 }

 /* Keeps hover and keyboard focus readable when the Show Errors action is in its error state. */
 .identity-import-errors-button.has-errors:hover,
 .identity-import-errors-button.has-errors:focus-visible {
 color: #ffffff;
 background: #b42318;
 border-color: #b42318;
 }

 /* Gives newly reported validation errors a short attention cue that does not alter layout. */
 .identity-import-errors-button.is-attention {
