 min-height: 48px;
 position: relative;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 padding: 10px 20px;
 color: #5b6860;
 font-size: 13px;
 font-weight: 750;
 text-decoration: none;
 }

 .reviewer-task-tabs > a:hover,
 .reviewer-task-tabs > a:focus-visible,
