 right: 14px;
 bottom: 0;
 left: 14px;
 background: #177645;
 }

 .reviewer-assignment-table {
 min-width: 840px;
 }

 .reviewer-assignment-title {
 width: 34%;
 min-width: 240px;
 }

 .reviewer-deadline-overdue {
 color: #b42318;
 font-weight: 750;
 }

 .reviewer-assignment-detail-heading {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 16px;
 }

 .reviewer-assignment-detail-grid {
 display: grid;
 grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
 align-items: stretch;
 gap: 12px;
 }

 .reviewer-assignment-details {
 display: grid;
 grid-template-columns: repeat(2, minmax(0, 1fr));
 gap: 0 18px;
 margin: 0;
 padding: 8px 18px 18px;
 }

 .reviewer-assignment-details > div {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(82px, 0.75fr) minmax(0, 1.25fr);
 gap: 10px;
 border-bottom: 1px solid #e8edea;
 padding: 11px 0;
 }

 .reviewer-assignment-details dt {
 color: #445268;
 font-size: 12px;
 font-weight: 750;
 }

 .reviewer-assignment-details dd {
 min-width: 0;
 margin: 0;
 overflow-wrap: break-word;
 word-break: normal;
 font-size: 12px;
 line-height: 1.5;
 }

 .reviewer-assignment-details .reviewer-assignment-detail-wide {
 grid-column: 1 / -1;
 }

 .reviewer-assignment-details .reviewer-study-overview {
 grid-template-columns: minmax(82px, 18%) minmax(0, 1fr);
 }

 .reviewer-study-overview dt,
 .reviewer-study-overview dd {
 text-align: left;
 }

 .reviewer-document-table {
 min-width: 760px;
 }

 .reviewer-document-table th,
 .reviewer-document-table td {
 text-align: center;
 vertical-align: middle;
 }

 .reviewer-document-table .reviewer-document-primary-column {
 text-align: left;
 }

 .reviewer-document-table td:nth-child(2) strong {
 display: inline-block;
 max-width: 280px;
 overflow-wrap: anywhere;
 }

 .reviewer-document-table button.dashboard-action-link {
