 }

 .res-selected-reviewer-list,
 .res-confirmation-reviewers {
 min-height: 148px;
 display: grid;
 align-content: start;
 gap: 8px;
 margin: 0;
 padding: 14px 16px;
 list-style: none;
 }

 .res-selected-reviewer-list li,
 .res-confirmation-reviewers li {
 min-width: 0;
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto auto;
 align-items: center;
 gap: 10px;
 border: 1px solid #cfe2d6;
 border-radius: 6px;
 padding: 10px;
 background: #f8fcf9;
